for name, fn in (("q10 ", fast_q10), ("q12 ", fast_q12), ("q12i", fast_q12i)):
    worst = 0.0
    for s in STATES:
        e = fn(s) - ref(s)
        if e < 0:
            e = -e
        if e > worst:
            worst = e
    print("  ", name, "max |err|", worst)
